def eqx_j2000(J):
    """The equinox of date as a J2000 direction."""
    P = precession(J)
    return [P[0][0], P[0][1], P[0][2]]


def date_to_j2000(J, v):
    return mvT(precession(J), v)


def ecl_date(J, lam):
    e = (23.4393 - 0.013 * (J - 2451545) / 36525) * DEG
    return [math.cos(lam * DEG), math.sin(lam * DEG) * math.cos(e), math.sin(lam * DEG) * math.sin(e)]


