def skyline(az):
    az = norm360(az)
    dN = abs((az + 540) % 360 - 180)
    rough = 0.9 * math.sin(az * 0.31 + 0.4) + 0.55 * math.sin(az * 0.93 + 2.1) + 0.3 * math.sin(az * 2.7 + 1.3) + 0.15 * math.sin(az * 6.1)
    north = math.cos(dN / 112 * math.pi / 2) ** 0.75 if dN < 112 else 0.0
    south = max(0.0, min(1.0, (dN - 100) / 20))
    return north * (6.2 + 1.3 * rough) + south * (1.5 + 0.35 * math.sin(az * 0.45 + 1) + 0.2 * math.sin(az * 1.7) + 0.08 * math.sin(az * 5.3)) + (1 - north - south) * 0.4


